<script setup lang="ts">import{onMounted,ref}from'vue';import{resumeApi,type Resume}from'../api/modules';import{ElMessage}from'element-plus';const list=ref<Resume[]>([]),selected=ref<Resume>(),loading=ref(true),uploading=ref(false),error=ref('');async function load(){loading.value=true;try{list.value=await resumeApi.list();if(list.value.length&&!selected.value)selected.value=list.value[0]}catch(e){error.value=(e as Error).message}finally{loading.value=false}}async function upload(options:any){uploading.value=true;try{const r=await resumeApi.upload(options.file);ElMessage.success('简历已保存并完成模型解析');await load();selected.value=r;options.onSuccess()}catch(e){options.onError(e);ElMessage.error((e as Error).message)}finally{uploading.value=false}}function parsed(r?:Resume){try{return r?JSON.parse(r.parsedJson):null}catch{return null}}onMounted(load)</script>
<template><section class="page-head"><div><h2>我的简历</h2><p>上传文件会依次经过 MinIO 保存、Tika 提取、模型结构化和 MySQL 持久化。</p></div></section><el-upload :http-request="upload" :show-file-list="false" accept=".pdf,.doc,.docx"><button class="primary-button" :disabled="uploading"><el-icon><Upload/></el-icon>{{uploading?'解析中…':'上传 PDF / Word'}}</button></el-upload><div v-if="loading" class="state-card">加载简历中</div><div v-else-if="error" class="state-card error">{{error}} <button @click="load">重试</button></div><div v-else-if="!list.length" class="state-card">暂无简历，请先上传。未配置模型时系统不会生成假结果。</div><section v-else class="two-column"><aside class="panel data-list"><div v-for="r in list" :key="r.id" :class="['resume-item',{active:selected?.id===r.id}]" @click="selected=r"><div><el-icon><Document/></el-icon></div><span><b>{{r.fileName}}</b><small>版本 V{{r.versionNo}} · {{r.createdAt}}</small></span></div></aside><article class="panel parsed-card" v-if="selected"><div class="panel-title"><div><h3>{{selected.fileName}}</h3><small>结构化结果来自模型，仅包含原文信息</small></div><router-link :to="`/optimize?resumeId=${selected.id}`">诊断优化 →</router-link></div><pre>{{JSON.stringify(parsed(selected),null,2)}}</pre></article></section></template>
